import React, { useState } from 'react';
import {
  JxForm,
  JxFormField,
  JxInput,
  JxSelect,
  JxSelectOption,
  JxSwitch,
  JxButton,
  JxStack,
  JxLabel,
} from '@jinx-ui/react';

type Language = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

const ProfileSettingsForm: React.FC<ProfileSettingsFormProps> = ({ onSave }) => {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<Language>('ru');
  const [emailNotifications, setEmailNotifications] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <JxForm onSubmit={handleSubmit} className="jx-p-4">
      <JxStack direction="column" gap="md">
        <JxFormField>
          <JxLabel htmlFor="profile-name">Имя</JxLabel>
          <JxInput
            id="profile-name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Введите имя"
          />
        </JxFormField>

        <JxFormField>
          <JxLabel htmlFor="profile-language">Язык интерфейса</JxLabel>
          <JxSelect
            id="profile-language"
            value={language}
            onChange={(value) => setLanguage(value as Language)}
          >
            <JxSelectOption value="ru">Русский</JxSelectOption>
            <JxSelectOption value="en">Английский</JxSelectOption>
          </JxSelect>
        </JxFormField>

        <JxFormField>
          <JxStack direction="row" align="center" gap="sm">
            <JxSwitch
              id="profile-email-notifications"
              checked={emailNotifications}
              onChange={(checked) => setEmailNotifications(checked)}
            />
            <JxLabel htmlFor="profile-email-notifications">
              Уведомления на почту
            </JxLabel>
          </JxStack>
        </JxFormField>

        <JxButton type="submit" variant="primary">
          Сохранить
        </JxButton>
      </JxStack>
    </JxForm>
  );
};

export default ProfileSettingsForm;

